mapper.select:
select T.workStatus, T.settleDate, T.prodName, T.prodId, sum(T.tradeAmt) tradeAmt,
T.ccy,
T.hasChildren, T.childInfo, T.parentInfo, T.otherPortfolioId from (select '待处理' as workStatus, null as tradeId , /*交易编号*/ to_date(#{platDate},'yyyy-mm-dd') as settleDate, /**交易日sysdate modify by yanyan on 20191121 取当前平台日*/ fp.FINPROD_NAME as prodName,/*产品名称*/ fp.FINPROD_MARKET_ID as prodId,/*产品代码*/ pcp.AMOUNT as tradeAmt,/*交易金额*/ null as portfolioId,/*子组合代码*/ null as portfolioName,/*子组合名称*/ pcp.CCY as ccy,/*币种*/ null as allotAmt, /*分配金额*/ '02' hasChildren, CONCAT('待处理',nvl(fp.FINPROD_MARKET_ID,'null')) childInfo, 'root' parentInfo, pcp.PORTFOLIO_ID otherPortfolioId from PTL_CASH_POSITION_FLOW pcp /*组合现金流水*/ inner join PTL_CAPACCT_INFO pci on pci.PORTFOLIO_ID=pcp.PORTFOLIO_ID and pci.CCY=pcp.CCY and pci.ACCT_NO=pcp.ACCT_ID and pci.ACCT_TYPE=#{acctType} inner join FIN_PRODUCT_ADD fpa /*标的类金融产品附属表*/ on pcp.PORTFOLIO_ID=fpa.PORTFOLIO_ID inner join (select * from FIN_PRODUCT where 1=1
and FINPROD_MARKET_ID in (
#{item}
)
) fp /*标的类金融产品*/ on fp.FINPROD_ID=fpa.FINPROD_ID and fp.FINPROD_TYPE2 not in (#{dfinprodType2}) inner join PTL_PORTFOLIO ptp /*组合*/ on pcp.PORTFOLIO_ID=ptp.PARENT_PORTFOLIO_ID where pcp.HODING_TYPE=#{hodingType} /*实际*/ and pcp.PORTFOLIO_ID in ( select ppa.PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY ppa where ppa.USER_ID=#{userId} )
and pcp.SPLIT_TYPE=#{splitType} or pcp.SPLIT_TYPE is null group by fp.FINPROD_NAME,fp.FINPROD_MARKET_ID, pcp.CCY,pcp.AMOUNT,pcp.seqNo ,pcp.PORTFOLIO_ID ) T group by T.prodName,T.prodId,T.CCY,T.otherPortfolioId,T.childInfo, T.workStatus, T.settleDate,T.hasChildren, T.parentInfo
